class Solution:
    def totalNQueens(self, n: int) -> int:
        def dfs(path, n):
            if len(path) == n:
                return 1
            res = 0
            for i in range(n):
                if is_eligible(i, path):
                    path.append(i)
                    res += dfs(path, n)
                    path.pop()
            return res

        def is_eligible(i, path):
            return all(i != x for x in path)

        return dfs([], n)
```

